1241→ * show a different head version do NOT overwrite — session stays consistent.
1242→ *
1243→ * Write ops (update / patch / files/write / files/remove) use overwrite
1244→ * semantics: the response's new version becomes the pin. Since a successful
1245→ * write already means "we won the optimistic lock at expected_version", the
1246→ * new head is what subsequent reads/writes in this session should target.
1247→ *
1248→ * Delete does NOT lazy-pin — soft-delete doesn't advance the version, and
1249→ * the skill is now archived (further ops will likely 404 or 40901 anyway).
1250→ */
1251→async function tryLazyPin(
1252→  sub: string,
1253→  respText: string,
1254→  spaceId: string,
1255→  userId: string,
1256→  agentSource: string,
1257→  sessionKey: string,
1258→  pinRepo: PinRepoLike,
1259→): Promise<void> {
1260→  let env: { code?: number; data?: unknown };
1261→  try {
1262→    env = JSON.parse(respText) as { code?: number; data?: unknown };
1263→  } catch {
1264→    return;
1265→  }
1266→  if (env.code !== 0 || !env.data) return;
1267→
1268→  // Extract candidates: {skillId, version} pairs to consider pinning.
1269→  // Field paths per plugin/src/gateway/skill-handlers.ts response shapes:
1270→  //   search:    data.items[].skill_id + data.items[].version    (toSummary)
1271→  //   get:       data.skill_id          + data.version           (toSummary flattened)
1272→  //   files/read data.skill_id (nope!)  + data.version           (readFile returns {path, content, encoding, size_bytes, mime_type, version} — NO skill_id, so we need it from inbound)
1273→  //   update/patch/files_write/files_remove: data.skill_id + data.version (toSummary)
1274→  const data = env.data as Record<string, unknown>;
1275→
1276→  if (sub === "search") {
1277→    // search returns {items: [...]}. HSETNX-pin each hit's first-seen version.
1278→    const items = Array.isArray(data.items) ? data.items : [];
1279→    const pairs: Array<{ skillId: string; version: number }> = [];
1280→    for (const it of items) {
1281→      if (!it || typeof it !== "object") continue;
1282→      const rec = it as Record<string, unknown>;
1283→      const id = rec.skill_id;
1284→      const v = rec.version;
1285→      if (typeof id === "string" && typeof v === "number") {
1286→        pairs.push({ skillId: id, version: v });
1287→      }
1288→    }
1289→    if (pairs.length > 0) {
1290→      await pinRepo.pinMany(spaceId, userId, agentSource, sessionKey, pairs);
1291→    }
1292→    return;
1293→  }
1294→
1295→  if (sub === "get") {
1296→    // get returns toSummary flat — skill_id and version at top level of data.
1297→    const id = data.skill_id;
1298→    const v = data.version;
1299→    if (typeof id === "string" && typeof v === "number") {
1300→      await pinRepo.pinMany(spaceId, userId, agentSource, sessionKey, [{ skillId: id, version: v }]);
1301→    }
1302→    return;
1303→  }
1304→
1305→  if (sub === "files/read") {
1306→    // files/read returns {path, content, encoding, size_bytes, mime_type, version}
1307→    // — NO skill_id. If pin already exists, skip; else we can't pin without id.
1308→    // (Read-side is already best-effort; missing pin just means next call also
1309→    // walks head. Acceptable.)
1310→    return;
1311→  }
1312→
1313→  if (WRITE_LOCK_OPS.has(sub)) {
1314→    // Write ops return toSummary — new head version at data.version.
1315→    // OVERWRITE semantics: we just successfully wrote, so this session should
1316→    // now target the new head for subsequent reads/writes.
1317→    const id = data.skill_id;
1318→    const v = data.version;
1319→    if (typeof id === "string" && typeof v === "number") {
1320→      await pinRepo.upsertVersion(spaceId, userId, agentSource, sessionKey, id, v);
1321→    }
1322→    return;
1323→  }
1324→
1325→  // Other subs (list / listing / versions / create / extract / delete):
1326→  // do not participate in lazy-pin.
1327→}
