 11→ *   资产 id · 版本 · 内容哈希(md5,与 Core 的 content_hash 同算法)· token 哈希(sha256)
 12→ *
 13→ * 任一不符即 verified:false;要明文的调用方必须走 plainTokensOrThrow,失败**明确中止**,
 14→ * 不静默降级(2026-09-11 审阅:读 head 不钉版本、不走管理读取、asPlainTokens 丢版本且不
 15→ * 拒绝 verified:false,gate-on 把错资产置 failed 后分析端读不到,静默变 not_delivered)。
 16→ *
 17→ * 读取走**管理路径**(`x-tdai-read-purpose: manage`,作者密钥与 user_id 匹配),所以资产
 18→ * 被闸门置为 candidate/failed 时同样读得到——闸门管的是模型路径,不是作者的管理读取。
 19→ *
 20→ * 离线路线(2026-09-12,审阅裁定"每个数字可从原始记录重算"必须在干净克隆上成立):干净克隆既无
 21→ * 作者密钥也无 Core。对**已烧毁**的值(明文已随记录进入 git 历史,按规则再也不能用)可以从
 22→ * 登记簿 `evaluation/attribution/burned-tokens.json` 取明文——登记簿只收 git 历史里已经有的值
 23→ * (build-burned-registry.mjs 逐个 `git grep` 证明),所以它不暴露任何新东西。走这条路的条件:
 24→ * `--offline` / TOKENS_OFFLINE=1,或密钥文件不存在且没有注入读取器。核验:版本 == 钉住的版本、
 25→ * 明文 sha256 集合 == 冻结的 token_sha256;content_hash 离线核不了,why 里写明。有密钥时登记簿
 26→ * 不参与:Core 的答案说了算,不做静默回退。
 27→ *
 28→ * 用法:
 29→ *   node evaluation/attribution/resolve-tokens.mjs [--task=DIR] [--key=FILE] [--out=FILE] [--offline]
 30→ *     --out 写出**明文形态**的 tokens.json(含 version),给运行时判定用;写到仓库外的临时
 31→ *     目录,用完即删。退出 0 = 全部 verified;1 = 有未 verified。
 32→ */
 33→import { readFileSync, writeFileSync, existsSync } from "node:fs";
 34→import { createHash } from "node:crypto";
 35→import { join, resolve, dirname } from "node:path";
 36→import { fileURLToPath } from "node:url";
 37→
 38→export const sha256Hex = (s) => createHash("sha256").update(String(s)).digest("hex");
 39→export const md5Hex = (s) => createHash("md5").update(String(s), "utf-8").digest("hex");
 40→
 41→const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
 42→const CORE_URL = process.env.CORE_URL ?? "http://localhost:8420";
 43→const SERVICE_ID = process.env.SERVICE_ID ?? "default";
 44→
 45→function keyFrom(file) {
 46→  const p = resolve(REPO, file);
 47→  if (!existsSync(p)) throw new Error(`key file missing: ${file}`);
 48→  const k = readFileSync(p, "utf8").replace(/\s+/g, "");
 49→  if (!k) throw new Error(`key file empty: ${file}`);
 50→  return k;
 51→}
 52→export const BURNED_REGISTRY = "evaluation/attribution/burned-tokens.json";
 53→/** The burned-value registry, or null when there is none; `file` may be absolute or repo-relative. */
 54→export function loadBurned(file) {
 55→  const p = resolve(REPO, file ?? process.env.TOKENS_BURNED_FILE ?? BURNED_REGISTRY);
 56→  if (!existsSync(p)) return null;
 57→  try { return JSON.parse(readFileSync(p, "utf8")); } catch { return null; }
 58→}
 59→/** Offline resolution of one asset from the registry: version pinned, sha256 set must equal the frozen one. */
 60→export function resolveBurned(id, spec, registry, { keyMissing = false } = {}) {
 61→  const pinVersion = spec.version ?? null;
 62→  const want = (spec.token_sha256 ?? []).map((h) => String(h).toLowerCase());
 63→  const base = { mode: "burned-offline", version: pinVersion, content_hash: spec.content_hash ?? null, token_sha256: spec.token_sha256 ?? [], read_purpose: null, adoption_fields: spec.adoption_fields ?? null };
 64→  const need = keyMissing ? "作者密钥文件不存在(干净克隆)" : "离线模式";
 65→  if (!registry) return { ...base, tokens: [], verified: false, why: `${need}:没有登记簿 ${BURNED_REGISTRY}(burned-tokens.json),也就无法离线取值;要么提供密钥 + Core,要么提供登记簿` };
 66→  const entry = registry?.[id]?.burned?.[String(pinVersion)] ?? null;
 67→  if (!entry || !Array.isArray(entry.tokens) || !entry.tokens.length) return { ...base, tokens: [], verified: false, why: `${need}:登记簿(burned-tokens.json)没有 ${id} 版本 ${pinVersion} 的已烧毁值` };
 68→  const got = entry.tokens.map(sha256Hex);
 69→  const ok = want.length > 0 && want.every((h) => got.includes(h)) && got.every((h) => want.includes(h));
 70→  if (!ok) return { ...base, tokens: [], verified: false, why: `${need}:登记簿里的明文 sha256 与冻结的 token_sha256 不一致` };
 71→  return { ...base, tokens: [...entry.tokens], verified: true, why: `${need}:明文取自已烧毁值登记簿,版本与 sha256 与冻结一致;content_hash 未经 Core 核验(离线核不了)` };
 72→}
 73→
 74→async function corePost(path, body, key, extraHeaders = {}) {
 75→  const res = await fetch(`${CORE_URL}${path}`, {
 76→    method: "POST",
 77→    headers: { "content-type": "application/json", "x-tdai-service-id": SERVICE_ID, authorization: `Bearer [REDACTED] "x-tdai-user-key": key, ...extraHeaders },
 78→    body: JSON.stringify(body),
 79→  });
 80→  return res.json().catch(() => ({ code: -1, message: `non-JSON (${res.status})` }));
 81→}
 82→
 83→/** 默认读取器:管理路径、钉版本。测试可注入替身。 */
 84→export function coreReader(key) {
 85→  return ({ team_id, user_id, agent_id, skill_id, version }) =>
 86→    corePost("/v3/skill/get", { team_id, user_id, agent_id, skill_id, version, include_content: true }, key, { "x-tdai-read-purpose": "manage" });
 87→}
 88→
 89→/**
 90→ * @param input  任务目录路径,或 { tokens, pair }
 91→ * @param opts   { read, keyFile, team_id, author_agent_id, author_user_id }
 92→ * @returns { [asset_id]: { mode, version, content_hash, tokens:[明文], token_sha256, adoption_fields,
 93→ *                          verified, read_purpose, why } }
 94→ */
 95→export async function resolveTokens(input, opts = {}) {
 96→  let tokens, pair;
 97→  if (typeof input === "string") {
 98→    const taskDir = resolve(REPO, input);
 99→    tokens = existsSync(join(taskDir, "tokens.json")) ? JSON.parse(readFileSync(join(taskDir, "tokens.json"), "utf8")) : {};
100→    pair = existsSync(join(taskDir, "pair.json")) ? JSON.parse(readFileSync(join(taskDir, "pair.json"), "utf8")) : {};
101→  } else {
102→    tokens = input?.tokens ?? {};
103→    pair = input?.pair ?? {};
104→  }
105→  const ids = Object.keys(tokens).filter((k) => !k.startsWith("_"));
106→  const team_id = opts.team_id ?? pair.team_id;
107→  const author_agent_id = opts.author_agent_id ?? pair.author_agent_id;
108→
109→  let key = null, read = opts.read ?? null, author_user_id = opts.author_user_id ?? null;
110→  const ensureReader = async () => {
111→    if (read) return;
112→    key = keyFrom(opts.keyFile ?? "deploy/global-images/.topic4-user-key");
113→    read = coreReader(key);
114→  };
115→  const ensureAuthorUser = async () => {
116→    if (author_user_id || !author_agent_id) return;
117→    if (!key) key = keyFrom(opts.keyFile ?? "deploy/global-images/.topic4-user-key");
118→    const ag = await corePost("/v3/meta/agent/get", { agent_id: author_agent_id }, key);
119→    author_user_id = ag?.data?.owner_user_id ?? null;
120→  };
