106→  /** 写入资源字节，校验 path 和 size。如果 path 已存在则覆盖。 */
107→  async writeResource(skillId: string, version: number, payload: SkillResourcePayload): Promise<SkillManifestEntry> {
108→    this.assertPath(payload.path);
109→    const buf = decodeContent(payload.content, payload.encoding);
110→    if (buf.length > this.maxBytes) {
111→      throw new SkillResourceError(
112→        "RESOURCE_TOO_LARGE",
113→        `${payload.path} (${buf.length} bytes) exceeds max ${this.maxBytes} bytes`,
114→      );
115→    }
116→    const key = this.fileKey(skillId, version, payload.path);
117→    const mime = payload.mime_type ?? guessMime(payload.path);
118→    const isExec = payload.is_executable ?? false;
119→    // 用 backend.putObject 直接写以保留 metadata（is_executable）
120→    await this.storage.getBackend().putObject(key, buf, {
121→      contentType: mime,
122→      metadata: { is_executable: isExec ? "1" : "0" },
123→    });
124→    return {
125→      path: payload.path,
126→      size_bytes: buf.length,
127→      mime_type: mime,
128→      is_executable: isExec,
129→    };
130→  }
